<?php require_once __DIR__.'/bootstrap.php'; $title='AniRead — Discover your next story'; $q=$pdo->query("SELECT * FROM anime ORDER BY popularity IS NULL,popularity ASC LIMIT 12"); $trending=$q->fetchAll(); $featured=$trending[0]??null; include __DIR__.'/includes/header.php'; if($featured): ?><section class="hero" style="background-image:linear-gradient(90deg,var(--bg),transparent),url('<?=e($featured['banner']?:$featured['poster'])?>')"><div class="hero-copy"><span class="eyebrow">FEATURED ANIME</span><h1><?=e($featured['title'])?></h1><p><?=e(mb_strimwidth($featured['synopsis']??'',0,260,'…'))?></p><div class="meta">★ <?=e($featured['score']?:'—')?> · <?=e($featured['type']?:'Anime')?> · <?=e($featured['year']?:'—')?></div><br><div class="actions"><a class="btn" href="<?=url('anime.php?id='.$featured['id'])?>">Details</a><a class="btn alt" href="<?=url('watch.php?id='.$featured['id'])?>">Watch Now</a></div></div><img class="poster" src="<?=e($featured['poster']?:'assets/placeholder.svg')?>" alt=""></section><?php endif; ?><section class="section"><h2>Trending now</h2><div class="grid"><?php foreach($trending as $a) card($a); ?></div></section><?php include __DIR__.'/includes/footer.php';
